// 💠 DIAMANT VGT SUPREME STATUS
use serde::{Deserialize,Serialize};use std::collections::{BTreeMap,BTreeSet};use vgt_object_model::WorkspaceDocument;use crate::{assets::{validate_asset,ThemeAssetRef},tokens::{validate_tokens,ThemeTokens},ThemeError};
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="kebab-case")]pub enum BrandKitScope{Local,Vault,Space}
#[derive(Debug,Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct BrandKit{pub id:String,pub version:u64,pub scope:BrandKitScope,pub scope_id:String,pub logos:Vec<ThemeAssetRef>,pub fonts:Vec<ThemeAssetRef>,pub colors:BTreeMap<String,String>,pub chart_styles:BTreeMap<String,String>,pub page_defaults:BTreeMap<String,String>,pub approved_asset_ids:BTreeSet<String>,pub theme_tokens:ThemeTokens}
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct BrandKitUpdatePreview{pub from_version:u64,pub to_version:u64,pub changed_tokens:Vec<String>,pub affected_object_ids:Vec<String>,pub adoption_is_explicit:bool}
pub fn validate_brand_kit(k:&BrandKit)->Result<(),ThemeError>{if k.id.is_empty()||k.id.len()>128||k.scope_id.is_empty()||k.scope_id.len()>256||k.version==0||k.logos.len()>32||k.fonts.len()>64||k.approved_asset_ids.len()>2048{return Err(ThemeError::Bounds("brand-kit".into()));}validate_tokens(&k.theme_tokens)?;for a in k.logos.iter().chain(k.fonts.iter()){validate_asset(a)?;}Ok(())}
fn changed(a:&ThemeTokens,b:&ThemeTokens)->BTreeSet<String>{let ja=serde_json::to_value(a).unwrap_or_default();let jb=serde_json::to_value(b).unwrap_or_default();let mut out=BTreeSet::new();for section in ["palette","semantic_colors","typography","spacing","effects","chart_colors"]{if ja.get(section)!=jb.get(section){out.insert(section.into());}}out}
pub fn preview_brand_kit_update(doc:&WorkspaceDocument,current:&BrandKit,next:&BrandKit)->Result<BrandKitUpdatePreview,ThemeError>{validate_brand_kit(current)?;validate_brand_kit(next)?;if current.id!=next.id||next.version<=current.version{return Err(ThemeError::Invalid("brand-kit-version".into()));}let c=changed(&current.theme_tokens,&next.theme_tokens);let mut affected:Vec<String>=if c.is_empty(){Vec::new()}else{doc.objects.keys().cloned().collect()};affected.sort();Ok(BrandKitUpdatePreview{from_version:current.version,to_version:next.version,changed_tokens:c.into_iter().collect(),affected_object_ids:affected,adoption_is_explicit:true})}
